 static string SourceKey(JsonObject p){
  // Name changes at the provider must not discard the customer's local edit.
  JsonNode? Canonical(JsonNode? node)=>node switch{JsonObject o=>new JsonObject(o.OrderBy(x=>x.Key,StringComparer.Ordinal).Select(x=>new KeyValuePair<string,JsonNode?>(x.Key,Canonical(x.Value)))),JsonArray a=>new JsonArray(a.Select(Canonical).ToArray()),_=>node?.DeepClone()};
  return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(Canonical(p["outbounds"])!.ToJsonString())));
 }
