  save.Click+=(_,_)=>{if(png==null)return;using var picker=new SaveFileDialog{Filter="PNG image (*.png)|*.png",FileName=ServerList.StripFlags(group.Profiles[index]["remarks"]?.ToString()??"configuration")+".png"};if(picker.ShowDialog(dialog)==DialogResult.OK)File.WriteAllBytes(picker.FileName,png);};close.Click+=(_,_)=>dialog.Close();dialog.FormClosed+=(_,_)=>image.Image?.Dispose();TranslateTree(dialog);ApplyTheme(dialog);Motion.Dialog(dialog);return dialog;
 }
 static byte[] CreateQrPng(string text){using var generator=new QRCodeGenerator();using var data=generator.CreateQrCode(text,QRCodeGenerator.ECCLevel.M);return new PngByteQRCode(data).GetGraphic(6);}
